class Shape:
    def area(self):
        return 0

class Rect(Shape):
    def __init__(self, w, h):
        self.w = w
        self.h = h

    def area(self):
        return self.w * self.h

shapes = [Rect(2, 3), Rect(1, 4)]
print(sum(s.area() for s in shapes))

